// Generated by philote from page /projects. PageBody's body is written by
// a model and pinned in philote.lock (decision-2).
/* eslint-disable @typescript-eslint/no-unused-vars -- every page gets the same imports */
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import * as Icons from "lucide-react";

import { projects } from "@/lib/api";
import { must } from "@/lib/backend";
import { readProjectCard } from "@/lib/reads";
import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";

import ProjectCard from "@/components/common/project-card";

export const metadata: Metadata = { title: "Projects" };

export default function Page() {
    return (
        <main className="flex flex-1 flex-col">
            <PageBody
                title={"Projects"}
                content={(className) => (
                    <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                        <Records className={className} />
                    </Suspense>
                )}
            />
        </main>
    );
}

// Records puts every card in one element with the layout's class, so the
// layout decides how the cards are arranged.
async function Records({ className }: { className: string }) {
    await connection();
    const records = await must(projects.list());
    if (records.length === 0) {
        return <p className="text-muted-foreground">{"No projects yet. Start one."}</p>;
    }
    const items = await Promise.all(records.map(readProjectCard));
    return (
        <div className={className}>
            {items.map((item) => (
                <ProjectCard key={item.project.id} {...item} />
            ))}
        </div>
    );
}

type PageBodyProps = {
    title: string;
    content: (className: string) => React.ReactNode;
};

function PageBody({ title, content }: PageBodyProps): React.ReactNode {
    return (
      <div className="mx-auto flex w-full max-w-5xl flex-col gap-6 px-4 py-6 sm:px-6 sm:py-8 lg:py-10">
        <header className="flex flex-col gap-2">
          <div className="flex items-center gap-3">
            <span className="flex size-9 items-center justify-center rounded-lg bg-secondary text-secondary-foreground">
              <Icons.FolderKanban className="size-5" />
            </span>
            <h1 className="font-heading text-2xl font-semibold tracking-tight text-foreground sm:text-3xl">
              {title}
            </h1>
          </div>
          <p className="text-sm text-muted-foreground">
            Browse every project in one place.
          </p>
        </header>
        <Separator orientation="horizontal" />
        {content(
          "grid w-full grid-cols-1 items-stretch gap-4 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 lg:gap-6 [&>*]:h-full [&>*]:w-full"
        )}
      </div>
    );
}
